<?php
declare(strict_types=1);require __DIR__.'/_bootstrap.php';api_method('GET');if(!Auth::check())json_response(['ok'=>false,'message'=>'Authentication required'],401);if(!in_array(Auth::user()['role']??'', ['coach','technical','admin'],true))json_response(['ok'=>false,'message'=>'Forbidden'],403);
if((Auth::user()['role']??'')==='coach'){$stmt=db()->prepare("SELECT r.id,r.participant_name,r.institution,r.status,r.rejection_reason,s.name skill_name,z.name zone_name FROM registrations r JOIN skills s ON s.id=r.skill_id JOIN zones z ON z.id=r.zone_id WHERE r.coach_user_id=? ORDER BY r.created_at DESC");$stmt->execute([Auth::id()]);}else{$stmt=db()->query("SELECT r.id,r.participant_name,r.institution,r.status,r.rejection_reason,s.name skill_name,z.name zone_name,u.full_name coach_name FROM registrations r JOIN skills s ON s.id=r.skill_id JOIN zones z ON z.id=r.zone_id JOIN users u ON u.id=r.coach_user_id ORDER BY r.created_at DESC LIMIT 1000");}json_response(['ok'=>true,'data'=>$stmt->fetchAll()]);
